/* Agent Rise pilot extensions. Supabase stores account data; the Agent Rise
   platform owns the application, integrations, and provider callbacks. */
const pilot = { db:null,user:null,demo:false,loaded:false,revision:0,calls:[],carriers:[],events:[],workspaceData:{dailyGoal:5,campaigns:[],referrals:[],freshPourNotes:{},tripIncentives:[],agentInfo:{}},dirty:false,saving:false,saveAgain:false,rcReady:false,rcAuthorized:false,rcCalls:new Map(),seenCalls:new Set(),pendingLogs:[],lastSaved:null };
const config = {...window.AGENT_RISE_CONFIG};
const SUPABASE_CONFIG_ROTATION_MIGRATION = "agentRiseSupabaseKeyRotation20260919";
if (localStorage.getItem(SUPABASE_CONFIG_ROTATION_MIGRATION) !== "complete") {
  localStorage.removeItem("agentRisePublicConfig");
  localStorage.setItem(SUPABASE_CONFIG_ROTATION_MIGRATION, "complete");
}
const $ = id => document.getElementById(id);
const html = escapeHtml;
const uid = () => crypto.randomUUID();
const iso = () => new Date().toISOString();
function revisionValue(value) {
    if (typeof value === "number" && Number.isFinite(value) && value >= 0) return value;
    if (typeof value === "string" && /^\d+$/.test(value)) return Number(value);
    return 0;
}
function permissionExpiry(value) {
  if(!/^\d{4}-\d{2}-\d{2}$/.test(value||'')) return '';
  const [y,m,d]=value.split('-').map(Number);
  const original=new Date(Date.UTC(y,m-1,d));
  if(original.toISOString().slice(0,10)!==value) return '';
  const end=new Date(Date.UTC(y+1,m,0)).getUTCDate();
  return `${y+1}-${String(m).padStart(2,'0')}-${String(Math.min(d,end)).padStart(2,'0')}`;
}
function permissionDays(p){const end=permissionExpiry(p.ptcSignedDate);return end?Math.round((Date.parse(end)-Date.parse(todayIsoDate()))/86400000):null;}
function permissionBadge(p){const d=permissionDays(p);return d!==null&&d>=0&&d<=30?`<span class="due-badge">PTC expires in ${d} days</span>`:'';}
function contactBlock(p,{automated=false}={}) {
  if(!p) return 'Select a saved prospect first.';
  if(p.leadPool==='Do Not Contact'||p.clientStatus==='Do Not Contact'||p.marketingEligibility==='Do Not Market'||p.qualificationStatus==='Do Not Market')return 'This contact is marked Do Not Contact / Do Not Market.';
  if(!p.ptcSource||p.ptcSource==='Not on File'||permissionDays(p)===null||permissionDays(p)<0||p.ptcSignedDate>todayIsoDate())return 'Record a valid, unexpired permission to contact (PTC) before proceeding.';
  if(/medicare|\bpdp\b|turning 65/i.test(p.product||'')&&(p.soaCompleted!=='Yes'||!p.soaDate||p.soaDate>todayIsoDate()||!p.soaMethod||p.soaMethod==='Not Applicable'))return 'This Medicare-related prospect needs a completed, dated SOA and its recording method before proceeding.';
  if(automated&&p.marketingEligibility!=='Active Insurance Prospect')return 'Call-E requires Active Insurance Prospect marketing eligibility.';
  return '';
}
function allowContact(p,options){const reason=contactBlock(p,options);if(reason){alert(reason);return false;}return true;}
function prospectActions(p){return `<button class="button button-secondary" type="button" data-action="log-call" data-id="${html(p.id)}">Log Call</button>${pilot.rcAuthorized&&pilot.rcReady?`<button class="button button-secondary" type="button" data-action="ringcentral" data-id="${html(p.id)}">RingCentral</button>`:''}${p.appointmentDate?`<button class="button button-secondary" type="button" data-action="call-e" data-task="confirm" data-id="${html(p.id)}">Confirm Appointment</button>`:''}${p.leadPool==='New Lead Pool'?`<button class="button button-secondary" type="button" data-action="call-e" data-task="screen" data-id="${html(p.id)}">Screen New Lead</button>`:''}${p.nextFollowUp?`<button class="button button-secondary" type="button" data-action="call-e" data-task="follow-up" data-id="${html(p.id)}">Follow Up</button>`:''}`;}
function dialog(id,title,body,wide=false){document.body.insertAdjacentHTML('beforeend',`<dialog id="${id}" class="pilot-dialog ${wide?'pilot-wide':''}" aria-labelledby="${id}Title"><h2 id="${id}Title">${title}</h2>${body}</dialog>`);return $(id);}
function closeButton(id){return `<button type="button" class="button button-secondary" data-close="${id}">Close</button>`;}
function notify(message,error=false){$('saveState').textContent=message;$('pilotStatus').dataset.error=String(error);}
function scrubErrorText(value){return String(value??'').replace(/sb_secret_[A-Za-z0-9_-]+/g,'[redacted Supabase secret]').replace(/(authorization\s*[:=]\s*bearer\s+)[^\s,"']+/gi,'$1[redacted]').replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g,'[redacted token]');}
function errorDetail(error){if(!error)return '(no details supplied)';if(typeof error==='string')return scrubErrorText(error);const values={message:error.message,code:error.code,details:error.details,hint:error.hint,status:error.status,source:error.source};return Object.entries(values).filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`${k}: ${scrubErrorText(v)}`).join('\n')||scrubErrorText(String(error));}
function reportError(title,error){const tray=$('ar-error-tray'),textEl=$('ar-error-text');if(!tray||!textEl)return;pilot.lastErrorReport=`--- AGENT RISE ERROR REPORT ---\nTime: ${iso()}\nWhere: ${scrubErrorText(title)}\nDetail:\n${errorDetail(error)}\n--------------------------------`;textEl.textContent=pilot.lastErrorReport;tray.hidden=false;}
function field(id,label,type='text',options=null){return `<div class="field"><label for="${id}">${label}</label>${options?`<select id="${id}">${options.map(v=>`<option>${html(v)}</option>`).join('')}</select>`:`<input id="${id}" type="${type}" ${id==='ptcExpirationDate'?'readonly':''}>`}</div>`;}
