  dialog('accountDialog','Agent Rise Pro',`<div id="authLanding" class="auth-view"><p class="auth-subhead">Medicare Advantage Agent Operating System</p><p class="auth-promise">Built by a seasoned agent, for agents. Run your whole book — leads, calls, follow-ups, and compliance — from one place.</p><div class="auth-choice-row"><button class="button button-primary" id="tryDemo" type="button">Try the Demo</button><button class="button auth-gold" id="showSignIn" type="button">Sign In</button></div><p class="auth-trial">Start your 7-Day Free Trial. No messy contracts. Cancel anytime.</p></div><div id="authSignIn" class="auth-view" hidden><h3>Welcome back</h3><div id="accountState" class="pilot-notice"></div><form id="connectionForm">${field('loginEmail','Email','email')}${field('loginPassword','Password','password')}<button class="button button-primary" type="submit">Sign In</button></form><button class="auth-link" id="showSignup" type="button">Create account</button><button class="auth-link" id="showForgot" type="button">Forgot password?</button><button class="auth-link" data-auth-view="landing" type="button">Back</button></div><div id="authSignup" class="auth-view" hidden><h3>Create your account</h3><form id="signupForm">${field('signupEmail','Email','email')}${field('signupPassword','Password','password')}<ul class="password-rules" data-password-rules="signup"><li data-rule="length">✓ At least 12 characters</li><li data-rule="upper">✓ One uppercase letter</li><li data-rule="lower">✓ One lowercase letter</li><li data-rule="number">✓ One number</li><li data-rule="symbol">✓ One symbol (!@#$%^&amp;*)</li></ul><button class="button button-primary" type="submit">Create account</button></form><button class="auth-link" data-auth-view="signin" type="button">Already have an account? Sign in</button></div><div id="authForgot" class="auth-view" hidden><h3>Reset your password</h3><form id="forgotForm">${field('forgotEmail','Email','email')}<button class="button button-primary" type="submit">Send reset link</button></form><p id="forgotState" class="pilot-notice" hidden></p><button class="auth-link" data-auth-view="signin" type="button">Back to Sign In</button></div><div id="authRecovery" class="auth-view" hidden><h3>Choose a new password</h3><form id="recoveryForm">${field('recoveryPassword','New password','password')}<ul class="password-rules" data-password-rules="recovery"><li data-rule="length">✓ At least 12 characters</li><li data-rule="upper">✓ One uppercase letter</li><li data-rule="lower">✓ One lowercase letter</li><li data-rule="number">✓ One number</li><li data-rule="symbol">✓ One symbol (!@#$%^&amp;*)</li></ul><button class="button button-primary" type="submit">Update password</button></form><p id="recoveryState" class="pilot-notice" hidden></p><button class="auth-link" id="recoveryRetry" type="button" hidden>Request another reset link</button></div>`);

