  dialog('callDialog','Log Call',`<p id="callPerson"></p><form id="callForm">${field('callOutcome','Outcome','text',['','Reached','No Answer','Voicemail','Callback Requested','Appointment Set','Appointment Confirmed','Appointment Held','Application Submitted','Declined','Wrong Number'])}${field('callNextDate','Next follow-up (optional)','date')}<div id="callAppointmentWrap" hidden>${field('callAppointment','Appointment date and time','datetime-local')}</div><label for="callNote">Note (optional)</label><textarea id="callNote" rows="2"></textarea><button class="button button-primary" type="submit">Save call</button>${closeButton('callDialog')}</form>`);
  dialog('statsDialog','Performance',`<label for="statsRange">Period</label><select id="statsRange"><option value="week">This week</option><option value="month">This month</option></select><div id="statsContent"></div>${closeButton('statsDialog')}`,true);
  dialog('carriersDialog','Carrier & contracting desk',`<p>Keep your own contracts, writing numbers and rates here. Estimates use your entered rates; missing rates are shown as missing.</p><p class="pilot-muted">CMS 2026 reference (initial / renewal): MA national $694 / $347; CT, PA and DC $781 / $391; CA and NJ $864 / $432; PR and USVI $474 / $237. PDP $114 / $57. Actual carrier rates govern your estimates. <a href="https://www.cms.gov/medicare/health-drug-plans/managed-care-marketing/medicare-marketing-guidelines/agent-broker-compensation" target="_blank" rel="noopener noreferrer">Check current CMS data and regional limits</a>. <a href="https://22041182.fs1.hubspotusercontent-na1.net/hubfs/22041182/3_Miscellaneous/Official_CMS_Documents/memo-agent-broker-compensation-and-training-and-testing-requirements-cy2026.pdf" target="_blank" rel="noopener noreferrer">CMS 2026 rate memo (June 18, 2025)</a>.</p><form id="carrierForm"><input id="carrierId" type="hidden"><div class="pilot-grid">${field('carrierName','Carrier name')}${field('carrierProducts','Products (MA, PDP, Supplement, Ancillary)')}${field('carrierStates','States available')}${field('carrierPath','Contracting path','text',['Direct','FMO','IMO'])}${field('carrierWriting','Writing number')}${field('carrierInitial','Initial commission ($)','number')}${field('carrierRenewal','Renewal commission ($)','number')}${field('carrierDeadline','Appointment deadline','date')}${field('carrierJit','JIT available','text',['No','Yes'])}${field('carrierPortal','Your portal URL','url')}</div><label for="carrierNotes">Notes</label><textarea id="carrierNotes" rows="2"></textarea><button class="button button-primary" type="submit">Save carrier</button><button class="button button-secondary" id="clearCarrier" type="button">New carrier</button></form><div id="carrierRows" class="pilot-scroll"></div>${closeButton('carriersDialog')}`,true);
  $('carrierName').required=true;['carrierInitial','carrierRenewal'].forEach(id=>{$(id).min='0';$(id).step='0.01';});
  dialog('migrationDialog','Existing browser contacts found',`<p id="migrationSummary"></p><p>Your original browser data will remain unchanged.</p><button id="acceptMigration" class="button button-primary" type="button">Import to this account</button><button id="declineMigration" class="button button-secondary" type="button">Leave in browser</button>`);
