  dialog('learningLibraryDialog','Info-graph Library',`<p>Reference materials recovered from the September 19 build. Confirm current CMS, Social Security, carrier and agency requirements before client-facing use.</p><div class="library-grid"><article class="library-card"><img src="assets/images/Medicare_Social_Security_Payment_Matrix.png" alt="Medicare and Social Security Payment Matrix preview"><h3>Medicare &amp; Social Security Payment Matrix</h3><p>Automatic, voluntary and direct premium payment paths.</p><a class="button button-primary" href="assets/images/Medicare_Social_Security_Payment_Matrix.png" download>Download infograph</a></article><article class="library-card"><img src="assets/images/Medicare_Advantage_Agent_Launch_Blueprint.png" alt="Medicare Advantage Agent Launch Blueprint preview"><h3>Medicare Advantage Agent Launch Blueprint</h3><p>Certification, revenue structure and retention overview.</p><a class="button button-primary" href="assets/images/Medicare_Advantage_Agent_Launch_Blueprint.png" download>Download infograph</a></article><article class="library-card"><img src="assets/images/2026_Income_Surcharge_Cheat_Sheet.png" alt="2026 Income Surcharge Cheat Sheet preview"><h3>2026 Income Surcharge Cheat Sheet</h3><p>IRMAA brackets, adjustments and SSA-44 appeal reminders.</p><a class="button button-primary" href="assets/images/2026_Income_Surcharge_Cheat_Sheet.png" download>Download infograph</a></article><article class="library-card"><h3>Medicare Field Guide / Agent Notebook</h3><p>Offline reference and working guide from the earlier build.</p><a class="button button-primary" href="assets/md/Medicare_Field_Guide_Agent_Notebook.md" download>Download field guide</a></article></div>${closeButton('learningLibraryDialog')}`,true);
