function tpmoDisclaimer(){
  if(!$('tpmoStatus'))return '';
  const applicable=$('tpmoStatus').value!=='Not Applicable';
  const complete=!applicable||['tpmoOrganizations','tpmoPlans'].every(id=>/^\d+$/.test($(id).value)&&Number($(id).value)>0);
  [elements.copyScriptButton,elements.downloadScriptButton].forEach(button=>{button.disabled=!complete;button.title=complete?'':'Enter organization and plan counts before copying or downloading.';});
  if(!applicable)return '';
  const count=id=>/^\d+$/.test($(id).value)&&Number($(id).value)>0?$(id).value:'[enter count]';
  const base=`Currently we represent ${count('tpmoOrganizations')} organizations which offer ${count('tpmoPlans')} products in your area. `;
  return '\n\nTPMO DISCLAIMER — read before discussing benefits:\n'+($('tpmoStatus').value==='All Plans Represented'?base+'You can always contact Medicare.gov or 1-800-MEDICARE for help with plan choices.':'We do not offer every plan available in your area. '+base+'Please contact Medicare.gov or 1-800-MEDICARE to get information on all of your options.');
}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function normalizeWorkspaceData(value={}){
  const safeArray=v=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object').map(x=>({...x,id:/^[0-9a-f-]{36}$/i.test(x.id||'')?x.id:uid()})):[];
  const notes=value.freshPourNotes&&typeof value.freshPourNotes==='object'&&!Array.isArray(value.freshPourNotes)?Object.fromEntries(Object.entries(value.freshPourNotes).map(([k,v])=>[String(k),String(v||'')])):{};
  const dailyGoal=value.dailyGoal===undefined?5:Math.max(0,Number.parseInt(value.dailyGoal,10)||0);
  const agentInfo=value.agentInfo&&typeof value.agentInfo==='object'?{avatar:String(value.agentInfo.avatar||'male'),npn:String(value.agentInfo.npn||''),specialization:String(value.agentInfo.specialization||''),states:String(value.agentInfo.states||''),homeState:String(value.agentInfo.homeState||''),timezone:String(value.agentInfo.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)}:{timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};
  return {dailyGoal,campaigns:safeArray(value.campaigns),referrals:safeArray(value.referrals),freshPourNotes:notes,tripIncentives:safeArray(value.tripIncentives),agentInfo};
}
