  const set=new Set(ev.filter(e=>e.type==='appointment-set').map(e=>e.prospectId));const held=new Set(ev.filter(e=>e.type==='appointment-held').map(e=>e.prospectId));const apps=new Set(ev.filter(e=>e.type==='application').map(e=>e.prospectId));const closes=new Set([...ev.filter(e=>e.type==='close').map(e=>e.prospectId),...state.prospects.filter(p=>p.closingDate&&inside(p.closingDate)&&(p.status==='Client'||p.policyStatus==='Active')).map(p=>p.id)]);
  return {leads:state.prospects.filter(p=>inside(p.createdAt)).length,calls:calls.length,reached:reached.size,set:set.size,held:held.size,applications:apps.size,closes:closes.size};
