  const reached=new Set(pilot.calls.filter(c=>!c.attemptOnly).map(c=>c.prospectId)),appointed=new Set(pilot.events.filter(e=>e.type==='appointment-set').map(e=>e.prospectId)),apps=new Set([...pilot.events.filter(e=>e.type==='application').map(e=>e.prospectId),...state.prospects.filter(p=>p.status==='Application').map(p=>p.id)]),closed=new Set(state.prospects.filter(p=>p.status==='Client'||p.policyStatus==='Active').map(p=>p.id));
