  $('campaignRows').innerHTML=pilot.workspaceData.campaigns.map(c=>`<p><strong>${html(c.name)}</strong> · ${html(c.channel)} <button class="button button-danger" type="button" data-campaign-delete="${html(c.id)}">Delete</button></p>`).join('')||'<p class="pilot-muted">No saved campaigns.</p>';
  $('referralRows').innerHTML=pilot.workspaceData.referrals.map(r=>`<p><strong>${html(r.name)}</strong> from ${html(r.from)} · ${html(r.status)} <button class="button button-danger" type="button" data-referral-delete="${html(r.id)}">Delete</button></p>`).join('')||'<p class="pilot-muted">No referral requests.</p>';
