  const prospect=normalizeProspect({id:uid(),firstName:first,lastName:$('leadLast').value.trim(),stateRegion:$('leadState').value.trim(),product:$('leadInterest').value.trim()||'Not selected',preferredContact:$('leadMethod').value,source:$('leadSource').value,campaign:$('leadCampaign').value.trim(),phone:permission?$('leadPhone').value.trim():'',email:permission?$('leadEmail').value.trim().toLowerCase():'',ptcSource:permission?'Other':'Not on File',ptcSignedDate:permission?todayIsoDate():'',soaCompleted:'No',soaDate:'',soaMethod:'Not Applicable',leadPool:'Contact Review Pool',qualificationStatus:'Review Needed',marketingEligibility:'Review Needed',clientStatus:'Prospect',policyStatus:'None',status:'New Lead',createdAt:iso(),notes:permission?'Lead Desk capture: permission to contact recorded.':'Lead Desk capture: no contact permission recorded; contact details were not stored.'});
  state.prospects.unshift(prospect);await persistWorkspace();$('leadCaptureForm').reset();redraw();notify(`Added ${fullName(prospect)} to Contact Review Pool.`);
