function connectRingCentral(){const clientId=config.ringCentralClientId||'',redirect=config.ringCentralRedirectUri||'';if(!clientId||!safeUrl(redirect)){alert('RingCentral is not configured. Ask the Agent Rise administrator for help.');return;}$('rcPanel').hidden=false;if($('rcFrame'))return;const frame=document.createElement('iframe');frame.id='rcFrame';frame.title='RingCentral phone';frame.allow='microphone; autoplay';const url=new URL('https://apps.ringcentral.com/integration/ringcentral-embeddable/latest/app.html');url.searchParams.set('clientId',clientId);url.searchParams.set('redirectUri',redirect);url.searchParams.set('disableInactiveTabCallEvent','1');frame.src=url.href;$('rcHost').append(frame);$('rcStatus').textContent='Sign in to RingCentral. The built-in phone remains available.';setTimeout(()=>{if(!pilot.rcReady)$('rcStatus').textContent='RingCentral is not ready. Use the built-in phone or check your connection.';},15000);}
function dialRingCentral(id){const p=state.prospects.find(p=>p.id===id);if(!allowContact(p))return;if(!phoneDisplay(p.phone).dial)return alert('Add a valid phone number.');if(!pilot.rcAuthorized||!pilot.rcReady)return alert('RingCentral is not ready. Use the built-in phone.');pilot.pendingDial={prospectId:id,phoneNumber:p.phone,calledAt:iso()};$('rcPanel').hidden=false;$('rcFrame').contentWindow.postMessage({type:'rc-adapter-new-call',phoneNumber:p.phone,toCall:true},'https://apps.ringcentral.com');}
async function startAutomatedCall(id,task){const p=state.prospects.find(p=>p.id===id);if(!allowContact(p,{automated:true}))return;if(!phoneDisplay(p.phone).dial)return alert('Add a valid phone number.');if(!confirm(`Ask Call-E to ${task==='confirm'?'confirm the appointment':task==='screen'?'screen this lead':'follow up'} with ${fullName(p)}?`))return;try{if(!pilot.user||!config.callEEndpoint)throw Error('Call-E is not connected. Configure the Agent Rise endpoint in Account, or call manually.');if(pilot.dirty&&!await persistWorkspace())throw Error('Save this prospect before requesting an automated call.');const {data,error}=await pilot.db.auth.getSession();if(error||!data.session)throw Error('Sign in again.');const response=await fetch(config.callEEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${data.session.access_token}`},body:JSON.stringify({prospectId:id,task,requestId:uid()})});const result=await response.json();if(!response.ok&&result.logged){if(!pilot.dirty)await loadAccount(pilot.user);alert(result.error||'Call-E is unavailable. The attempt was logged.');return;}if(!response.ok)throw Error(result.error||'Call-E is unavailable.');notify('Call-E request accepted. Refresh account for the result.');}catch(e){pilot.calls.push({id:uid(),prospectId:id,phoneNumber:p.phone,direction:'outbound',duration:0,calledAt:iso(),outcome:'Automation unavailable',notes:e.message,attemptOnly:true});await persistWorkspace();alert(e.message);}}
