function addActionPair(target,saveLabel,exitAction){if(!target||target.dataset.actionPairs==='yes')return;target.dataset.actionPairs='yes';const make=()=>{const row=document.createElement('div');row.className='edit-action-pair';row.innerHTML=`<button class="button action-save" type="button">${saveLabel}</button><button class="button action-exit" type="button">Exit</button>`;row.querySelector('.action-save').onclick=()=>target instanceof HTMLFormElement?target.requestSubmit():target.click();row.querySelector('.action-exit').onclick=exitAction;return row;};if(target instanceof HTMLFormElement){target.prepend(make());target.append(make());}else{target.parentElement.insertBefore(make(),target);target.insertAdjacentElement('afterend',make());}}
function addPanelActionPairs(panel,saveLabel,saveAction,exitAction){if(!panel||panel.dataset.actionPairs==='yes')return;panel.dataset.actionPairs='yes';const make=()=>{const row=document.createElement('div');row.className='edit-action-pair';row.innerHTML=`<button class="button action-save" type="button">${saveLabel}</button><button class="button action-exit" type="button">Exit</button>`;row.querySelector('.action-save').onclick=saveAction;row.querySelector('.action-exit').onclick=exitAction;return row;};panel.prepend(make());panel.append(make());}
